	while (Q--) {
		read(opt), read(r1), read(c1), read(r2), read(c2);
		if (opt == 3) {
			//int a = my.ask(r1, c1), b = my.ask(r2, c2);
			//printf("%d %d\n", a, b);
			puts(my.ask(r1, c1) == my.ask(r2, c2) ? "Yes" : "No");
		} else if (opt == 1) {
